    const c = await commentService.createComment(t.actors.member, { orgId: t.org.id, issueId: issue.id, body: "reidx comment", parentId: null, mentionedUserIds: [] });
    getDb().delete(searchIndex).run();
    const env = { orgId: t.org.id, actorId: null, occurredAt: new Date().toISOString() } as any;
    await emit("search.reindex_requested", { ...env, subjectKind: "comment", subjectId: c.id });
    await emit("search.reindex_requested", { ...env, subjectKind: "project", subjectId: t.project.id });
    const r = await q(t, "reidx", { kinds: ["comment"], projectId: t.project.id });
    expect(r.total).toBe(1);
    const pr = await q(t, "", { kinds: ["project"] }).catch(() => null);
    const all = await q(t, t.project.name, { kinds: ["project"] });
    expect(all.total).toBe(1);
    await issueService.archiveIssue(t.actors.member, t.org.id, issue.id);
    await emit("search.reindex_requested", { ...env, subjectKind: "issue", subjectId: issue.id });
    expect((await q(t, "reidx issue")).total).toBe(0);
  });
});
