const SEARCH_QUERY_BUCKET = "search:query";

/**
 * Runs a query against the denormalised index (ADR 0007). The service is the
 * gate: with `advanced_search` the query's `kind:` / `project:` tokens narrow
 * the search; without it the whole query is literal text and only issues are
 * searched, whatever kinds the caller asked for. No query is ever refused for
 * its syntax.
 */
export async function search(
  actor: Actor,
  input: SearchQueryInput,
): Promise<Page<SearchHit>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));

  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Search rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await orgRepo.findOrgById(input.orgId);
  const advanced = isEnabled("advanced_search", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  const parsed = parseSearchQuery(input.q, advanced, input.kinds);
  const text = normaliseQuery(parsed.text);
  const page = await searchRepo.searchDocuments({
    ...input,
    q: text,
    kinds: [...parsed.kinds],
    projectId: parsed.projectId ?? input.projectId,
  });

  return {
    items: page.items.map((row) => ({
      kind: row.subjectKind,
      id: row.subjectId,
      title: row.content.split("\n")[0] ?? row.subjectId,
      snippet: snippetAround(row.content, text),
      href: hrefFor(row.subjectKind, row.subjectId),
    })),
    nextCursor: page.nextCursor,
    total: page.total,
  };
}

/**
 * Tidies the free text left once `parseSearchQuery` has removed the field
 * tokens, so the index only ever sees the free text.
 */
function normaliseQuery(raw: string): string {
  return raw.trim().replace(/\s+/g, " ");
}

